package com.tripmateai.controller;
import com.tripmateai.dto.request.chat.ChatMessageRequest; import com.tripmateai.dto.response.ApiResponse; import com.tripmateai.dto.response.chat.*; import com.tripmateai.service.ChatService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/chat") @RequiredArgsConstructor public class ChatController { private final ChatService service; @PostMapping("/message") public ResponseEntity<ApiResponse<ChatMessageResponse>> message(@Valid @RequestBody ChatMessageRequest request){return ResponseUtils.created(service.sendMessage(request),"Chat response generated");} @GetMapping("/history") public ResponseEntity<ApiResponse<List<ChatHistoryResponse>>> history(@RequestParam(required=false) Long tripId){return ResponseUtils.success(service.getChatHistory(tripId),"Chat history retrieved");} }
